import os
import base64
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _image_bytes_from_input(image_input: Any) -> bytes:
    if isinstance(image_input, bytes):
        return image_input
    if isinstance(image_input, str):
        if image_input.startswith("data:"):
            header, b64_data = image_input.split(",", 1)
            return base64.b64decode(b64_data)
        if os.path.isfile(image_input):
            with open(image_input, "rb") as f:
                return f.read()
        return image_input.encode("utf-8")
    raise TypeError("image_input must be bytes, a file path, or a data URI string")


def detect_text(image_input: Any, region_name: Optional[str] = None) -> List[Dict[str, Any]]:
    """
    Detect text in a static image using Amazon Rekognition.

    Args:
        image_input: Image bytes, local file path, or data URI string.
        region_name: Optional AWS region name.

    Returns:
        A list of dictionaries describing detected text.
    """
    image_bytes = _image_bytes_from_input(image_input)
    client = boto3.client("rekognition", region_name=region_name)

    try:
        response = client.detect_text(Image={"Bytes": image_bytes})
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Amazon Rekognition detect_text failed: {e}") from e

    detections: List[Dict[str, Any]] = []
    for item in response.get("TextDetections", []):
        geometry = item.get("Geometry", {})
        bbox = geometry.get("BoundingBox", {})
        detections.append(
            {
                "detected_text": item.get("DetectedText", ""),
                "confidence": float(item.get("Confidence", 0.0)),
                "type": item.get("Type", ""),
                "id": item.get("Id"),
                "parent_id": item.get("ParentId"),
                "bounding_box": {
                    "left": float(bbox.get("Left", 0.0)),
                    "top": float(bbox.get("Top", 0.0)),
                    "width": float(bbox.get("Width", 0.0)),
                    "height": float(bbox.get("Height", 0.0)),
                },
            }
        )

    return detections
